// src/v2/index.ts
import { createREST } from "@abacatepay/rest";
import { Routes } from "@abacatepay/types/v2";
var AbacatePay = ({ secret, rest }) => {
  const client = createREST({
    secret,
    ...rest,
    version: 2
  });
  return {
    rest: client,
    customers: {
      get(id) {
        return client.get(Routes.customers.get(id));
      },
      delete(id) {
        return client.post(Routes.customers.delete, {
          body: { id }
        });
      },
      create(body) {
        return client.post(Routes.customers.create, { body });
      },
      list(query) {
        return client.get(Routes.customers.list(query));
      }
    },
    checkouts: {
      create(body) {
        return client.post(Routes.checkouts.create, { body });
      },
      list(query) {
        return client.get(Routes.checkouts.list(query));
      },
      get(id) {
        return client.get(Routes.checkouts.get(id));
      },
      refund(id, reason) {
        return client.post(Routes.checkouts.refund, { body: { id, reason } });
      }
    },
    paymentLinks: {
      create(body) {
        return client.post(Routes.paymentLinks.create, { body });
      },
      list(query) {
        return client.get(Routes.paymentLinks.list(query));
      },
      get(id) {
        return client.get(Routes.paymentLinks.get(id));
      },
      refund(id, reason) {
        return client.post(Routes.paymentLinks.refund, { body: { id, reason } });
      }
    },
    pix: {
      create(body) {
        const wireBody = {
          method: "PIX",
          data: body
        };
        return client.post(Routes.transparents.create, { body: wireBody });
      },
      list(query) {
        return client.get(Routes.transparents.list(query));
      },
      simulate(id, metadata) {
        return client.post(Routes.transparents.simulatePayment(id), { body: { metadata } });
      },
      status(id) {
        return client.get(Routes.transparents.checkStatus(id));
      },
      refund(id, reason) {
        return client.post(Routes.transparents.refund, { body: { id, reason } });
      }
    },
    boleto: {
      create(body) {
        const wireBody = {
          method: "BOLETO",
          data: body
        };
        return client.post(Routes.transparents.create, { body: wireBody });
      }
    },
    transfers: {
      send(body) {
        return client.post(Routes.transfers.send, {
          body
        });
      },
      get(query) {
        return client.get(Routes.transfers.get(query));
      },
      list(query) {
        return client.get(Routes.transfers.list(query));
      }
    },
    coupons: {
      create(body) {
        return client.post(Routes.coupons.create, {
          body
        });
      },
      delete(id) {
        return client.post(Routes.coupons.delete, {
          body: { id }
        });
      },
      get(id) {
        return client.get(Routes.coupons.get(id));
      },
      list(query) {
        return client.get(Routes.coupons.list(query));
      },
      toggleStatus(id) {
        return client.post(Routes.coupons.toggleStatus, { body: { id } });
      }
    },
    store: {
      get() {
        return client.get(Routes.store.get);
      }
    },
    mrr: {
      get() {
        return client.get(Routes.mrr.get);
      },
      revenue({ startDate, endDate }) {
        return client.get(Routes.mrr.revenue(startDate, endDate));
      },
      merchant() {
        return client.get(Routes.mrr.merchant);
      }
    },
    payouts: {
      create(body) {
        return client.post(Routes.payouts.create, { body });
      },
      get(id) {
        return client.get(Routes.payouts.get(id));
      },
      list(query) {
        return client.get(Routes.payouts.list(query));
      }
    },
    subscriptions: {
      create(body) {
        return client.post(Routes.subscriptions.create, { body });
      },
      list(query) {
        return client.get(Routes.subscriptions.list(query));
      },
      cancel(id) {
        return client.post(Routes.subscriptions.cancel, { body: { id } });
      },
      changePlan(id, body) {
        return client.post(Routes.subscriptions.changePlan, { body: { id, ...body } });
      },
      recordUsage(id, body) {
        return client.post(Routes.subscriptions.recordUsage, { body: { id, ...body } });
      }
    },
    products: {
      create(body) {
        return client.post(Routes.products.create, {
          body
        });
      },
      get(query) {
        return client.get(Routes.products.get(query));
      },
      list(query) {
        return client.get(Routes.products.list(query));
      },
      delete(id) {
        return client.post(Routes.products.delete(id));
      }
    },
    webhooks: {
      create(body) {
        return client.post(Routes.webhooks.create, {
          body
        });
      },
      list(query) {
        return client.get(Routes.webhooks.list(query));
      },
      get(id) {
        return client.get(Routes.webhooks.get(id));
      },
      delete(id) {
        return client.post(Routes.webhooks.delete, {
          body: { id }
        });
      }
    }
  };
};

// src/index.ts
import { API_BASE_URL, API_VERSION } from "@abacatepay/types";

// src/version.ts
var version = "2.0.3";

// src/index.ts
var ABACATEPAY_DOCS_URL = "https://docs.abacatepay.com/";
export {
  version,
  AbacatePay,
  API_VERSION,
  API_BASE_URL,
  ABACATEPAY_DOCS_URL
};
